#!/usr/bin/env bash
# generated by rcm-store-connect — release_status.sh: rcm role `status`: read the review state of both stores.
#
#   Runs in the workspace rcm made from a git_ref (repository root). Inputs arrive as environment variables:
#     RCM_INPUT_BUILD_NAME=X.Y.Z   the version to look at (empty = the newest versions the stores have)
#   Secrets: the folder rcm hands over in ${{secrets_env}}. Never printed.
#
#   Writes (build/.rcm-release/, RELEASE_WORK overrides) when the stores were read:
#     status.json   { schema, checked_at,
#                     ios { version, build, state, raw_state, release_type, phased {state, day} | null } | null,
#                     android { version, version_code, state, raw_state, user_fraction } | null }
#     `state` is one of preparing · waiting_for_review · in_review · approved · rejected · releasing ·
#     released · unknown. This script maps the store's own word (kept in raw_state) onto those eight; rcm
#     only draws them.
#   Exit codes (docs/release-contract.md §2):
#     0 read · 1 a store could not be read (nothing written; the page keeps the previous status) · 2 environment
#   Markers: ::rcm::steps::3 · ::rcm::step::… · ::rcm::summary::… last.
#
#   Safety built in — keep it:
#     · This role only reads. store_status() must not submit, release, publish or change anything.
#     · There is no release / submit / publish call in this file, and none may be added for this role.
#
#   --selftest   shims replace the store; proves: both stores read -> status.json, a store that cannot be read
#                -> 1 with no status.json, a state outside the eight is refused by the contract, no secrets -> 2.
set -euo pipefail
HERE="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"; SELF="$HERE/$(basename "${BASH_SOURCE[0]}")"; ROOT="$(cd "$HERE/../.." && pwd)"; cd "$ROOT"

CONTRACT="${RCM_CONTRACT_PY:-$HERE/rcm_contract.py}"
WORK="${RELEASE_WORK:-$ROOT/build/.rcm-release}"
SECRETS_ENV="{{secrets_env}}"
# 안 채워진 템플릿(`{{secrets_env}}` 그대로)도 셀프테스트로 돌아야 한다 — bash 5 는 이름이
# 아닌 것의 간접 확장을 거부한다. 이름이 아니면 셀프테스트용 이름을 쓴다(채운 사본은 그대로).
case "$SECRETS_ENV" in ""|[0-9]*|*[!A-Za-z0-9_]*) SECRETS_ENV=RCM_TEMPLATE_SECRETS_DIR;; esac
SECRETS_DIR="${!SECRETS_ENV:-}"
SHIM="${RELEASE_SHIM:-}"                                 # selftest only: ok | ios_only | unreadable | raw
SHIM_CALLS="${RELEASE_SHIM_CALLS:-/dev/null}"

usage() {
  echo "usage: [RCM_INPUT_BUILD_NAME=X.Y.Z] release_status.sh | release_status.sh --selftest" >&2
  exit 2
}

# ── project hook — the only place that talks to a store ──────────────────────────────────────────────
# store_status BUILD_NAME: read both stores, read-only, and print ONE JSON object:
#   { "ios": { "version": "1.2.0", "build": 185, "state": "approved", "raw_state": "PENDING_DEVELOPER_RELEASE",
#              "release_type": "MANUAL", "phased": null } | null,
#     "android": { "version": "1.2.0", "version_code": 185, "state": "in_review",
#                  "raw_state": "RELEASE_LIFECYCLE_STATE_IN_REVIEW", "user_fraction": null } | null }
#   null = this project does not ship to that store. Exit non-zero when a store cannot be read.
store_status() {
  if [ -n "$SHIM" ]; then shim_store_status "$@"; return $?; fi
  # TODO(project): with the credentials in "$SECRETS_DIR", read the App Store version ($1, or the newest)
  #   — appStoreState, its build, releaseType, phased release — and the Play production track's newest
  #   release. Map each store word onto the eight states above and keep the store word in raw_state.
  #   Read-only. Delete the two lines below when done.
  echo "store_status() is not implemented — fill the TODO(project) block in scripts/release/release_status.sh" >&2
  return 1
}

# ── selftest shim ────────────────────────────────────────────────────────────────────────────────────
shim_store_status() {
  echo "store_status '$1'" >>"$SHIM_CALLS"
  local ios='{"version": "1.2.0", "build": 185, "state": "approved", "raw_state": "PENDING_DEVELOPER_RELEASE", "release_type": "MANUAL", "phased": null}'
  local android='{"version": "1.2.0", "version_code": 185, "state": "in_review", "raw_state": "RELEASE_LIFECYCLE_STATE_IN_REVIEW", "user_fraction": null}'
  case "$SHIM" in
    ok)         echo "{\"ios\": $ios, \"android\": $android}";;
    ios_only)   echo "{\"ios\": $ios, \"android\": null}";;
    raw)        echo "{\"ios\": ${ios/\"approved\"/\"PENDING_DEVELOPER_RELEASE\"}, \"android\": $android}";;  # 정규화를 잊었다
    unreadable) return 7;;
    *) echo "unknown RELEASE_SHIM=$SHIM" >&2; return 9;;
  esac
}

# ── contract plumbing ────────────────────────────────────────────────────────────────────────────────
step()     { echo "::rcm::step::$1"; }
step_end() { echo "::rcm::step-end::$1"; }
finish()   { echo "::rcm::summary::$1"; exit "$2"; }
json_field() { python3 -c 'import json,sys; v=json.load(open(sys.argv[1])).get(sys.argv[2]); print("" if v is None else json.dumps(v, ensure_ascii=False))' "$1" "$2"; }

main() {
  local build_name="${RCM_INPUT_BUILD_NAME:-}" raw rc ios android args
  [ -z "$build_name" ] || [[ "$build_name" =~ ^[0-9]+\.[0-9]+\.[0-9]+$ ]] || { echo "RCM_INPUT_BUILD_NAME must be X.Y.Z or empty, got '$build_name'" >&2; usage; }
  [ -f "$CONTRACT" ] || { echo "missing $CONTRACT — reinstall with /rcm-store-connect" >&2; exit 2; }
  mkdir -p "$WORK"
  rm -f "$WORK/status.json"   # 이번에 읽은 것만 남긴다 — 못 읽었으면 페이지는 이전 상태를 그린다
  echo "::rcm::steps::3"

  step "preflight"
  if [ -z "$SECRETS_DIR" ] || [ ! -d "$SECRETS_DIR" ]; then
    step_end fail
    finish "BLOCKED(env) — secrets folder missing (\$$SECRETS_ENV)" 2
  fi
  step_end ok

  step "read stores"
  raw="$WORK/status-raw.json"
  rc=0; store_status "$build_name" >"$raw" || rc=$?
  if [ "$rc" != 0 ]; then
    step_end fail
    finish "failed — store_status() exit $rc; status not read, nothing written" 1
  fi
  step_end ok

  step "status.json"
  ios="$(json_field "$raw" ios 2>/dev/null || true)"; android="$(json_field "$raw" android 2>/dev/null || true)"
  args=(write status --out "$WORK/status.json")
  [ -n "$ios" ] && args+=(--ios-json "$ios")
  [ -n "$android" ] && args+=(--android-json "$android")
  if ! python3 "$CONTRACT" "${args[@]}"; then
    step_end fail
    finish "failed — store_status() output violates the contract (see log); nothing written" 1
  fi
  step_end ok
  finish "status read — ios=$(python3 -c 'import json,sys; d=json.load(open(sys.argv[1])); i=d.get("ios") or {}; a=d.get("android") or {}; print((i.get("state") or "-") + " android=" + (a.get("state") or "-"))' "$WORK/status.json") (read-only)" 0
}

# ── selftest ─────────────────────────────────────────────────────────────────────────────────────────
selftest() {
  local t rc fails=0
  t="$(mktemp -d)"; mkdir -p "$t/secrets"
  check() {  # $1 label · $2 expected rc · $3 actual · $4 assertion on status.json ('' = must not exist)
    if [ "$2" != "$3" ]; then echo "FAIL $1: exit $3, expected $2"; cat "$t/out"; fails=$((fails+1)); return; fi
    if [ -n "$4" ]; then
      if ! python3 -c "import json,sys; d=json.load(open(sys.argv[1])); assert $4, d" "$t/work/status.json"; then
        echo "FAIL $1: status.json assertion failed: $4"; fails=$((fails+1)); return
      fi
    elif [ -e "$t/work/status.json" ]; then
      echo "FAIL $1: status.json was written"; fails=$((fails+1)); return
    fi
    echo "  ok  $1"
  }
  run() {  # $1 shim · rest env
    local shim="$1"; shift
    rm -rf "$t/work" "$t/calls"; mkdir -p "$t/work"; rc=0
    env RELEASE_SHIM="$shim" RELEASE_SHIM_CALLS="$t/calls" RELEASE_WORK="$t/work" \
        "$SECRETS_ENV=$t/secrets" "$@" bash "$SELF" >"$t/out" 2>&1 || rc=$?
  }
  echo "[release_status] selftest ($SECRETS_ENV)"
  run ok RCM_INPUT_BUILD_NAME=1.2.0
  check "both stores read -> status.json, exit 0" 0 "$rc" "d['ios']['state']=='approved' and d['ios']['raw_state']=='PENDING_DEVELOPER_RELEASE' and d['android']['state']=='in_review' and d['android']['version_code']==185 and isinstance(d['checked_at'], str)"
  grep -q "^store_status '1.2.0'" "$t/calls" || { echo "FAIL the hook did not get the build name"; fails=$((fails+1)); }
  run ok;         check "no build name -> the newest versions, exit 0" 0 "$rc" "d['ios']['version']=='1.2.0'"
  run ios_only;   check "a project on one store -> android null" 0 "$rc" "d['android'] is None and d['ios']['state']=='approved'"
  run unreadable; check "store unreadable -> exit 1, no status.json" 1 "$rc" ""
  run raw;        check "a state outside the eight -> contract refuses, exit 1" 1 "$rc" ""
  run ok "$SECRETS_ENV=$t/none"; check "no secrets -> exit 2, no store call" 2 "$rc" ""
  [ ! -s "$t/calls" ] || { echo "FAIL the store was called without secrets"; fails=$((fails+1)); }
  run ok RCM_INPUT_BUILD_NAME=1.2; check "bad build name -> usage exit 2" 2 "$rc" ""
  rm -rf "$t"
  [ "$fails" = 0 ] && { echo "[release_status] selftest PASS — read-only, eight states, nothing written when a store cannot be read"; return 0; }
  echo "[release_status] selftest FAIL ($fails)"; return 1
}

case "${1:-}" in --selftest) selftest;; "") main;; *) usage;; esac
